        return b"", b"", b""
class FixedStreamReceiver:
    completed = False
    error = None
    def __init__(self, cl, buf):
        self.remain = cl
        self.buf = buf
    def __len__(self):
        return self.buf.__len__()
    def received(self, data):
        "See IStreamConsumer"
        rm = self.remain
        if rm < 1:
            self.completed = True
            return 0
        datalen = len(data)
        if rm <= datalen:
            self.buf.append(data[:rm])
            self.remain = 0
            self.completed = True
            return rm
        else:
            self.buf.append(data)
            self.remain -= datalen
            return datalen
