        return self.buf.getfile()
    def getbuf(self):
        return self.buf
class ChunkedReceiver:
    chunk_remainder = 0
    validate_chunk_end = False
    control_line = b""
    chunk_end = b""
    all_chunks_received = False
    trailer = b""
    def __init__(self, buf):
        self.buf = buf
    def __len__(self):
        return self.buf.__len__()
    def received(self, s):
        if self.completed:
            return 0
        orig_size = len(s)
        while s:
            rm = self.chunk_remainder
            if rm > 0:
                to_write = s[:rm]
                self.buf.append(to_write)
                written = len(to_write)
                s = s[written:]
                self.chunk_remainder -= written
                if self.chunk_remainder == 0:
                    self.validate_chunk_end = True
            elif self.validate_chunk_end:
                s = self.chunk_end + s
                pos = s.find(b"\r\n")
                if pos < 0 and len(s) < 2:
                    self.chunk_end = s
                    s = b""
                else:
                    self.chunk_end = b""
                    if pos == 0:
                        s = s[2:]
                    else:
                        self.error = BadRequest("Chunk not properly terminated")
                        self.all_chunks_received = True
                    self.validate_chunk_end = False
            elif not self.all_chunks_received:
                s = self.control_line + s
                pos = s.find(b"\r\n")
                if pos < 0:
                    self.control_line = s
                    s = b""
                else:
                    line = s[:pos]
                    s = s[pos + 2 :]
                    self.control_line = b""
                    line = line.strip()
                    if line:
                        semi = line.find(b";")
                        if semi >= 0:
                            line = line[:semi]
                        try:
                            sz = int(line.strip(), 16)
                        except ValueError:
                            self.error = BadRequest("garbage in chunked encoding input")
                            sz = 0
                        if sz > 0:
                            self.chunk_remainder = sz
                        else:
                            self.all_chunks_received = True
            else:
                trailer = self.trailer + s
                if trailer.startswith(b"\r\n"):
                    self.completed = True
                    return orig_size - (len(trailer) - 2)
                pos = find_double_newline(trailer)
                if pos < 0:
                    self.trailer = trailer
                    s = b""
                else:
                    self.completed = True
                    self.trailer = trailer[:pos]
                    return orig_size - (len(trailer) - pos)
        return orig_size
    def getfile(self):
        return self.buf.getfile()
    def getbuf(self):
        return self.buf

