            "all_count": all_count,
            "result_count": result_count,
            "paginator": paginator,
            "page_obj": page_obj,
            "object_list": page_obj.object_list,
            "user_can_create": self.permission_helper.user_can_create(user),
            "show_search": self.search_handler.show_search_form,
