        match = re.match(r'(?P<type>\||>+)\s*(?P<target>.*)', fmt)
        if not match:
            continue
        target = match.group('target')
        parts = target.split()
        if len(parts) == 1:
            logs.append(target)
        elif ['tee', '-a'] == parts[:2]:
            logs.append(parts[2])
    return list(set(logs))
