    parser.add_option("-d", "--daemon", action="store_true", dest="daemon",
                      help="runs in background as a daemon")
    parser.add_option("-k", "--kill", action="store_true", dest="kill",
                      help="kill pystemon daemon")
    parser.add_option("-s", "--stats", action="store_true", dest="stats",
                      help="display statistics about the running threads (NOT IMPLEMENTED)")
    parser.add_option("-v", action="store_true", dest="verbose",
                      help="outputs more information")
    parser.add_option("--debug", action="store_true", dest="debug", help="enable debugging output")
    (options, args) = parser.parse_args()
    if not options.config:
        if os.path.isfile('/etc/pystemon.yaml'):
            options.config = '/etc/pystemon.yaml'
        if os.path.isfile('pystemon.yaml'):
            options.config = 'pystemon.yaml'
        filename = sys.argv[0]
        config_file = filename.replace('.py', '.yaml')
        if os.path.isfile(config_file):
            options.config = config_file
        print(options.config)
    if not os.path.isfile(options.config):
        parser.error('Configuration file not found. Please create /etc/pystemon.yaml, pystemon.yaml or specify a config file using the -c option.')
        exit(1)
    logger = logging.getLogger('pystemon')
    if options.debug:
        logger.setLevel(logging.DEBUG)
    else:
        logger.setLevel(logging.INFO)
    if not options.daemon:
        formatter = logging.Formatter('[%(asctime)s] %(message)s')
        hdlr = logging.StreamHandler(sys.stdout)
        hdlr.setFormatter(formatter)
        logger.addHandler(hdlr)
    if options.daemon:
        formatter = logging.Formatter('pystemon[%(process)d]: %(message)s')
        hdlr = logging.handlers.SysLogHandler(address='/dev/log', facility=logging.handlers.SysLogHandler.LOG_DAEMON)
        hdlr.setFormatter(formatter)
        logger.addHandler(hdlr)
    config = None
    try:
        config = PystemonConfig(options.config, options.debug)
    except Exception as e:
        logger.error("unable to load configuration: {}".format(e))
        os._exit(1)
    if options.kill:
        pidfile = config.pidfile()
        if os.path.isfile(pidfile):
            f = open(pidfile, 'r')
            pid = f.read()
            f.close()
            os.remove(pidfile)
            print("Sending signal to pid: {}".format(pid))
            os.kill(int(pid), 2)
            os._exit(0)
        else:
            print("PID file not found. Nothing to do.")
            os._exit(0)
    if options.daemon:
        main_as_daemon(config)
    else:
        main(config)
class PystemonSendmail():
    def __init__(self, mailfrom, mailto, subject,
            server='127.0.0.1', port=25, tls=False, username=None, password=None, size_limit=1024*1024):
        self.mailfrom = mailfrom
        self.mailto = mailto
        self.subject = subject
        self.server = server
        self.port = port
        self.tls = tls
        self.username = username
        self.password = password
        self.size_limit = size_limit
    def __repr__(self):
        return 'PystemonSendmail[from={}][to={}]'.format(self.mailfrom, self.mailto)
    def is_same_as(self, other):
        res = False
        try:
            res = (isinstance(other, PystemonSendmail)
                    and
                    (self.mailfrom == other.mailfrom)
                    and
                    (self.mailto == other.mailto)
                    and
                    (self.subject == other.subject)
                    and
                    (self.server == other.server)
                    and
                    (self.port == other.port)
                    and
                    (self.tls == other.tls)
                    and
                    (self.username == other.username)
                    and
                    (self.password == other.password)
                    and
                    (self.size_limit == other.size_limit))
        except Exception as e:
            logger.error("Unable to compare PystemonSendmail instances: {}".format(e))
            pass
        return res
    def send_pastie_alert(self, pastie):
        msg = MIMEMultipart()
        alert = "Found hit for {matches} in pastie {url}".format(matches=pastie.matches_to_text(), url=pastie.public_url)
        msg['Subject'] = self.subject.format(subject=alert)
        msg['From'] = self.mailfrom
        recipients = []
        recipients.append(self.mailto)
        for match in pastie.matches:
            if match.to is not None:
                recipients.extend(match.ato)
        msg['To'] = ','.join(recipients)
        if len(pastie.pastie_content) > self.size_limit:
            part = MIMEBase('application', "text/plain")
            part.set_payload(pastie.pastie_content.decode('utf8'))
            Encoders.encode_base64(part)
            part.add_header('Content-Disposition', 'attachment; filename="{id}.txt"'.format(id=pastie.id))
            msg.attach(part)
            content = "*** Content to large to be displayed, see attachment ***"
        else:
            content = pastie.pastie_content.decode('utf8')
        message = '''
I found a hit for a regular expression on one of the pastebin sites.
The site where the paste came from :        {site}
The original paste was located here:        {url}
And the regular expressions that matched:   {matches}
Below (after newline) is the content of the pastie:
{content}
        '''.format(site=pastie.site.name, url=pastie.public_url, matches=pastie.matches_to_regex(), content=content)
        msg.attach(MIMEText(message))
        try:
            s = smtplib.SMTP(self.server, self.port)
            if self.tls:
                s.starttls()
            if self.username:
                s.login(self.username, self.password)
            s.sendmail(self.mailfrom, recipients, msg.as_string())
            s.close()
        except smtplib.SMTPException as e:
            logger.error("ERROR: unable to send email: {0}".format(e))
        except Exception as e:
            logger.error("ERROR: unable to send email. Are your email setting correct?: {e}".format(e=e))
class PastieSearch():
    def __init__(self, engine, regex):
        if 'regex-flags' in regex:
            self.regex_flags = regex['regex-flags']
            self.flags = eval(self.regex_flags)
        else:
            self.regex_flags = None
            self.flags = engine.IGNORECASE
        self.search = regex['search']
        try:
            self.re_search = engine.compile(self.search.encode(), self.flags)
        except Exception as e:
            raise ValueError("invalid search regex: %s" % e)
        self.exclude = regex.get('exclude')
        if self.exclude is not None:
            try:
                self.re_exclude = engine.compile(self.exclude.encode(), self.flags)
            except Exception as e:
                raise ValueError("invalid exclude regex: %s" % e)
        self.description = regex.get('description')
        if 'count' in regex:
            self.count = int(regex['count'])
        else:
            self.count = -1
        self.to = regex.get('to')
        if self.to is not None:
            self.ato = self.to.split(",")
        else:
            self.ato = []
        self.extra = {}
        for (k, v) in regex.items():
            if k in ['search', 'description', 'exclude', 'count', 'regex-flags', 'to']:
                continue
            self.extra[k] = v
        self.h = None
        logger.debug("[{0}]: compiled into: {1}".format(self.search, self.re_search))
    def __str__(self):
        return self.to_text()
    def __repr__(self):
        return self.to_regex()
    def match(self, string):
        m = self.re_search.findall(string)
        if not m:
            return False
        if (self.count > 0) and (len(m) < self.count):
            return False
        if self.exclude is not None:
            if self.re_exclude.search(string):
                return False
        return True
    def to_text(self):
        if self.description is None:
            return self.search
        return self.description
    def to_regex(self):
        return self.search
    def to_dict(self):
        if self.h is None:
            self.h = {'search': self.search}
            if self.description is not None:
                self.h['description'] = self.description
            if self.exclude is not None:
                self.h['exclude'] = self.exclude
            if self.count >= 0:
                self.h['count'] = self.count
            if self.to is not None:
                self.h['to'] = self.to
            if self.regex_flags is not None:
                self.h['regex-flags'] = self.regex_flags
            for (k, v) in self.extra.items():
                self.h[k] = v
        return self.h
class ThreadProxyList(threading.Thread):
    def __init__(self, proxies_list, wait=1):
        threading.Thread.__init__(self)
        self.list = proxies_list
        self.last_mtime = proxies_list.last_mtime
        self.wait = wait
        self.condition = threading.Condition()
        self.kill_received = False
    def __repr__(self):
        return 'ThreadProxyList[{}]'.format(self.list.filename)
    def stop(self):
        with self.condition:
            logger.info('ThreadProxyList exiting')
            self.kill_received = True
            self.condition.notify_all()
    def reset(self, wait=1):
        with self.condition:
            self.last_mtime = 0
            self.filename = filename
            self.wait = wait
    def run(self):
        logger.info('ThreadProxyList started')
        try:
            with self.condition:
                while not self.kill_received:
                    mtime = os.stat(self.list.filename).st_mtime
                    if mtime != self.last_mtime:
                        logger.debug('Proxy configuration file changed. Reloading proxy list.')
                        self.list.load_proxies_from_file()
                        self.last_mtime = mtime
                    self.condition.wait(1)
        except Exception as e:
            logger.error('ThreadProxyList crashed: {0}'.format(e))
        logger.info('ThreadProxyList exited')
class ProxyList():
    def __init__(self, filename):
        self.proxies_failed = []
        self.proxies_list = []
        self.proxies_lock = threading.Lock()
        self.thread_proxy_list = None
        self.filename = filename
        self.last_mtime = 0
        self.load_proxies_from_file()
    def monitor(self, wait=1):
        if self.thread_proxy_list:
            self.thread_proxy_list.reset(self, wait)
        else:
            t = ThreadProxyList(self, wait)
            t.setDaemon(True)
            t.start()
            self.thread_proxy_list = t
        return self.thread_proxy_list
    def load_proxies_from_file(self):
        try:
            filename = self.filename
            logger.debug('Loading proxy configuration from file "{file}" ...'.format(file=filename))
            proxies_list = []
            with self.proxies_lock, open(filename) as f:
                self.last_mtime = os.fstat(f.fileno()).st_mtime
                for line in f:
                    line = line.strip()
                    if line:
                        proxies_list.append(line)
                self.proxies_failed = []
                self.proxies_list = proxies_list
            logger.debug('Found {count} proxies in file "{file}"'.format(file=filename, count=len(proxies_list)))
        except Exception as e:
            logger.error('Configuration problem: error reading proxyfile "{file}": {e}'.format(file=filename, e=e))
    def get_random_proxy(self):
        proxy = None
        with self.proxies_lock:
            if self.proxies_list:
                proxy = random.choice(tuple(self.proxies_list))
        return proxy
    def failed_proxy(self,proxy):
        with self.proxies_lock:
            if len(self.proxies_list) == 1:
                logger.info("Failing proxy {} not removed as it's the only proxy left.".format(proxy))
            else:
                self.proxies_failed.append(proxy)
                if self.proxies_failed.count(proxy) >= 2 and proxy in self.proxies_list:
                    logger.info("Removing proxy {0} from proxy list because of to many errors errors.".format(proxy))
                    try:
                        self.proxies_list.remove(proxy)
                    except ValueError:
                        pass
                    logger.info("Proxies left: {0}".format(len(self.proxies_list)))

